/**
 * LocalQuranRepository - the default QuranRepository implementation.
 *
 * Serves canonical Qur'anic text and structural metadata from the verified
 * dataset generated by scripts/build-quran-data.mjs (Tanzil Uthmani Minimal
 * text + Tanzil Quran Metadata v1.0). No network calls, no database round
 * trips: a practice session can do thousands of lookups for free, and works
 * with the Qur'an API of the day completely offline.
 */
import uthmani from './data/uthmani.js';
import meta from './data/meta.js';
import { normalize, words as splitWords } from './normalize.js';
import { parseVerseKey, verseKey, boundaryOf } from './refs.js';

const TOTAL = meta.totalAyat;

// surah number -> surah record
const surahByNumber = new Map(meta.surahs.map((s) => [s.number, s]));
// startIndex of each surah, for reverse lookup
const surahStarts = meta.surahs.map((s) => s.startIndex);

const normalizedCache = new Array(TOTAL);
const wordCache = new Array(TOTAL);

export class LocalQuranRepository {
  get id() {
    return 'local';
  }

  get attribution() {
    return {
      text: 'Qur’an text: Tanzil.net Uthmani (minimal) edition',
      metadata: 'Structure: Tanzil Quran Metadata v1.0 (CC BY 3.0)',
      url: 'https://tanzil.net',
    };
  }

  // ---- index <-> key ------------------------------------------------------

  /** 0-based global ayah index for a verse key, or null when out of range. */
  indexOf(key) {
    const parsed = typeof key === 'string' ? parseVerseKey(key) : key;
    if (!parsed) return null;
    const surah = surahByNumber.get(parsed.surah);
    if (!surah || parsed.ayah > surah.ayahCount) return null;
    return surah.startIndex + parsed.ayah - 1;
  }

  /** Verse key for a global index. */
  keyAt(index) {
    if (index == null || index < 0 || index >= TOTAL) return null;
    const s = boundaryOf(surahStarts, index);
    const surah = meta.surahs[s];
    return verseKey(surah.number, index - surah.startIndex + 1);
  }

  get totalAyat() {
    return TOTAL;
  }

  // ---- surahs -------------------------------------------------------------

  listSurahs() {
    return meta.surahs;
  }

  getSurah(number) {
    return surahByNumber.get(Number(number)) || null;
  }

  /** Every ayah of a surah. */
  getSurahAyat(number) {
    const surah = this.getSurah(number);
    if (!surah) return [];
    return this.getRangeByIndex(surah.startIndex, surah.startIndex + surah.ayahCount - 1);
  }

  // ---- ayat ---------------------------------------------------------------

  /** One ayah with its text and structural position. Null when unknown. */
  getAyah(key) {
    const index = this.indexOf(key);
    if (index == null) return null;
    return this.#ayahAt(index);
  }

  #ayahAt(index) {
    const k = this.keyAt(index);
    const { surah, ayah } = parseVerseKey(k);
    if (!normalizedCache[index]) normalizedCache[index] = normalize(uthmani[index]);
    return {
      index,
      verseKey: k,
      surah,
      ayah,
      text: uthmani[index],
      textSimple: normalizedCache[index],
      page: this.pageOf(index),
      juz: this.juzOf(index),
      hizbQuarter: this.hizbQuarterOf(index),
      ruku: boundaryOf(meta.rukuStarts, index) + 1,
      manzil: boundaryOf(meta.manzilStarts, index) + 1,
      sajda: meta.sajdas.find((s) => s.index === index) || null,
      wordCount: this.getAyahWords(k).length,
    };
  }

  /**
   * Words of an ayah with 1-based positions - the addressing scheme used by
   * every Mistake row and every word-level drill.
   */
  getAyahWords(key) {
    const index = this.indexOf(key);
    if (index == null) return [];
    if (!wordCache[index]) {
      wordCache[index] = splitWords(uthmani[index]).map((text, i) => ({
        position: i + 1,
        text,
        simple: normalize(text),
      }));
    }
    return wordCache[index];
  }

  getWord(key, position) {
    return this.getAyahWords(key).find((w) => w.position === Number(position)) || null;
  }

  getNextAyah(key) {
    const i = this.indexOf(key);
    return i == null || i + 1 >= TOTAL ? null : this.#ayahAt(i + 1);
  }

  getPreviousAyah(key) {
    const i = this.indexOf(key);
    return i == null || i - 1 < 0 ? null : this.#ayahAt(i - 1);
  }

  // ---- ranges -------------------------------------------------------------

  getRangeByIndex(fromIndex, toIndex) {
    const lo = Math.max(0, Math.min(fromIndex, toIndex));
    const hi = Math.min(TOTAL - 1, Math.max(fromIndex, toIndex));
    const out = [];
    for (let i = lo; i <= hi; i++) out.push(this.#ayahAt(i));
    return out;
  }

  /** Inclusive ayah range between two verse keys. */
  getRange(fromKey, toKey) {
    const a = this.indexOf(fromKey);
    const b = this.indexOf(toKey);
    if (a == null || b == null) return [];
    return this.getRangeByIndex(a, b);
  }

  /** Number of ayat in an inclusive range (cheap - no text materialised). */
  countRange(fromKey, toKey) {
    const a = this.indexOf(fromKey);
    const b = this.indexOf(toKey);
    if (a == null || b == null) return 0;
    return Math.abs(b - a) + 1;
  }

  // ---- pages (Madani mushaf, 604 pages) -----------------------------------

  get pageCount() {
    return meta.pageStarts.length;
  }

  /** 1-based mushaf page for a global index. */
  pageOf(index) {
    return boundaryOf(meta.pageStarts, index) + 1;
  }

  pageOfKey(key) {
    const i = this.indexOf(key);
    return i == null ? null : this.pageOf(i);
  }

  /** All ayat on a mushaf page, plus the surahs that page spans. */
  getPage(pageNumber) {
    const p = Number(pageNumber);
    if (!Number.isInteger(p) || p < 1 || p > this.pageCount) return null;
    const start = meta.pageStarts[p - 1];
    const end = p === this.pageCount ? TOTAL - 1 : meta.pageStarts[p] - 1;
    const ayat = this.getRangeByIndex(start, end);
    const surahNumbers = [...new Set(ayat.map((a) => a.surah))];
    return {
      page: p,
      startIndex: start,
      endIndex: end,
      firstVerseKey: this.keyAt(start),
      lastVerseKey: this.keyAt(end),
      juz: this.juzOf(start),
      surahs: surahNumbers.map((n) => surahByNumber.get(n)),
      ayat,
    };
  }

  /** Page range covering an inclusive verse range. */
  pagesForRange(fromKey, toKey) {
    const a = this.indexOf(fromKey);
    const b = this.indexOf(toKey);
    if (a == null || b == null) return [];
    const lo = this.pageOf(Math.min(a, b));
    const hi = this.pageOf(Math.max(a, b));
    return Array.from({ length: hi - lo + 1 }, (_, i) => lo + i);
  }

  // ---- juz / hizb / rub ---------------------------------------------------

  juzOf(index) {
    return boundaryOf(meta.juzStarts, index) + 1;
  }

  hizbQuarterOf(index) {
    return boundaryOf(meta.hizbQuarterStarts, index) + 1; // 1..240
  }

  /** All ayat of a juz (1..30). */
  getJuz(juzNumber) {
    const j = Number(juzNumber);
    if (!Number.isInteger(j) || j < 1 || j > 30) return null;
    const start = meta.juzStarts[j - 1];
    const end = j === 30 ? TOTAL - 1 : meta.juzStarts[j] - 1;
    return {
      juz: j,
      startIndex: start,
      endIndex: end,
      firstVerseKey: this.keyAt(start),
      lastVerseKey: this.keyAt(end),
      firstPage: this.pageOf(start),
      lastPage: this.pageOf(end),
      ayahCount: end - start + 1,
    };
  }

  /** A hizb (1..60) resolved through its four quarters. */
  getHizb(hizbNumber) {
    const h = Number(hizbNumber);
    if (!Number.isInteger(h) || h < 1 || h > 60) return null;
    const start = meta.hizbQuarterStarts[(h - 1) * 4];
    const end = h === 60 ? TOTAL - 1 : meta.hizbQuarterStarts[h * 4] - 1;
    return {
      hizb: h,
      startIndex: start,
      endIndex: end,
      firstVerseKey: this.keyAt(start),
      lastVerseKey: this.keyAt(end),
      juz: this.juzOf(start),
    };
  }

  /** Page boundaries for a juz, used by the progress map. */
  getJuzPages(juzNumber) {
    const juz = this.getJuz(juzNumber);
    if (!juz) return [];
    return Array.from({ length: juz.lastPage - juz.firstPage + 1 }, (_, i) => juz.firstPage + i);
  }

  // ---- audio --------------------------------------------------------------

  /**
   * Ayah recitation URL. EveryAyah serves per-ayah MP3s over a plain CDN with
   * no key and no quota; if it is unreachable the UI degrades to text-only
   * practice rather than blocking the session.
   */
  getAudioUrl(key, reciter = 'Alafasy_128kbps') {
    const parsed = parseVerseKey(key);
    if (!parsed) return null;
    const s = String(parsed.surah).padStart(3, '0');
    const a = String(parsed.ayah).padStart(3, '0');
    return `https://everyayah.com/data/${reciter}/${s}${a}.mp3`;
  }

  /**
   * Word-level timestamps are not present in the local dataset. Returning null
   * (rather than guessing) lets the UI fall back to ayah-level highlighting.
   */
  getWordTimestamps() {
    return null;
  }
}

let singleton;

/** Process-wide repository instance. */
export function getQuranRepository() {
  if (!singleton) singleton = new LocalQuranRepository();
  return singleton;
}
